def solve(workspace):
    n = workspace.length
    # Bubble sort implementation: O(N^2) swaps
    # Since budget is unlimited, this is sufficient for any N.
    # We repeatedly scan the array and swap adjacent out-of-order elements.
    # We do n passes; after n passes, the array is guaranteed to be sorted.
    for _ in range(n):
        for i in range(n - 1):
            if workspace.peek(i) > workspace.peek(i + 1):
                workspace.swap_adjacent(i)

