def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an HxW grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2x3 tile can be placed as 3x2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 <= n <= 7)
        h: Height of the grid (1 <= h <= 10)
        w: Width of the grid (1 <= w <= 10)
        tiles: List of (a, b) tuples where tile i has dimensions axb (1 <= a, b <= 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    grid_area = h * w

    # Try all subsets of tiles
    for idx_subset in range(1, 1 << n):
        subset_tiles = []
        current_area = 0
        used_indices = []
        for i in range(n):
            if idx_subset & (1 << i):
                subset_tiles.append(tiles[i])
                current_area += tiles[i][0] * tiles[i][1]
                used_indices.append(i)

        if current_area != grid_area:
            continue

        # Check if we have duplicate tiles in the subset (since we need to handle replacement or identical types carefully)
        # Actually, the problem says 'Some tiles may remain unused', implying we select a subset of the provided list.
        # If the list contains duplicate tiles, we pick specific instances. Backtracking over indices handles this.

        grid_map = [[False] * w for _ in range(h)]

        def is_valid_placement(r, c, dim_h, dim_w):
            if r + dim_h > h or c + dim_w > w:
                return False
            for i in range(dim_h):
                for j in range(dim_w):
                    if grid_map[r + i][c + j]:
                        return False
            return True

        def place_tile(r, c, dim_h, dim_w):
            for i in range(dim_h):
                for j in range(dim_w):
                    grid_map[r + i][c + j] = True

        def remove_tile(r, c, dim_h, dim_w):
            for i in range(dim_h):
                for j in range(dim_w):
                    grid_map[r + i][c + j] = False

        # Sort subset tiles to allow consistent ordering, though not strictly necessary for correctness, helps determinism
        # However, simple iteration is fine.

        def solve(idx, count):
            if count == grid_area:
                return True
            if idx == len(subset_tiles):
                return False

            dim = subset_tiles[idx]
            h_t = dim[0]
            w_t = dim[1]

            # Original orientation
            for r in range(h - h_t + 1):
                for c in range(w - w_t + 1):
                    if is_valid_placement(r, c, h_t, w_t):
                        place_tile(r, c, h_t, w_t)
                        if solve(idx + 1, count + h_t * w_t):
                            return True
                        remove_tile(r, c, h_t, w_t)

            # Rotated orientation if different
            if h_t != w_t:
                for r in range(h - w_t + 1):
                    for c in range(w - h_t + 1):
                        if is_valid_placement(r, c, w_t, h_t):
                            place_tile(r, c, w_t, h_t)
                            if solve(idx + 1, count + w_t * h_t):
                                return True
                            remove_tile(r, c, w_t, h_t)

            return False

        if solve(0, 0):
            return True

    return False

from typing import List

def kth_smallest_amount(coins: List[int], k: int) -> int:
    coins = sorted(coins)
    min_coin = coins[0]

    def count_le(x: int) -> int:
        count = 0
        for c in coins:
            count += x // c
        return count

    low = 1
    high = k * min_coin
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if count_le(mid) >= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    # Precompute cost to make s[i:j] a semi-palindrome

    def get_semi_cost(i: int, j: int) -> int:
        length = j - i
        if length == 0 or length == 1:
            # Length 0 or 1 cannot be semi-palindrome per constraints
            return float('inf')

        best = float('inf')
        # Try all valid d such that 1 <= d < length and length % d == 0
        for d in range(1, length):
            if length % d == 0:
                groups = length // d
                total_changes = 0
                possible = True
                for rem in range(d):
                    chars = [s[i + offset] for offset in range(rem, length, d)]
                    if len(chars) < 2:
                        possible = False
                        break
                    cl = len(chars)
                    # Changes to make chars into palindrome
                    for x in range(cl // 2):
                        if chars[x] != chars[cl - 1 - x]:
                            total_changes += 1
                if possible:
                    best = min(best, total_changes)
        # Check if best is still inf (should not happen given constraints and examples)
        return best if best != float('inf') else float('inf')

    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length
            if length == 1:
                dp[i][j] = float('inf')
            else:
                cost = get_semi_cost(i, j)
                dp[i][j] = cost if cost != float('inf') else float('inf')

    # DP for partitioning
    INF = float('inf')
    min_changes = [INF] * (n + 1)
    min_changes[0] = 0

    for i in range(1, n + 1):
        for prev in range(i):
            if min_changes[prev] != INF:
                cost = get_semi_cost(prev, i)
                if cost != INF:
                    min_changes[i] = min(min_changes[i], min_changes[prev] + cost)

    return min_changes[k] if k <= n else -1

