def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    """ Given a weighted directed graph with n vertices (numbered 1 to n) and m edges,
    determine if there exists a walk that visits each vertex at least once.
    If such a walk exists, return the minimum total weight of edges traversed.
    If no such walk exists, return None.

    The graph is guaranteed not to contain negative cycles.
    Edges can be traversed multiple times, with their weight counted each time.

    Args:
        n: Number of vertices (2 <= n <= 20)
        m: Number of edges (1 <= m <= n*(n-1))
        edges: List of tuples (u, v, w) representing directed edges from u to v with weight w
               where 1 <= u, v <= n, u != v, and -10^6 <= w <= 10^6

    Returns:
        The minimum total weight if a valid walk exists, None otherwise.
    """
    if n < 2:
        return 0 if n == 1 else None

    # Build adjacency list and edge weights
    adj = {i: [] for i in range(1, n + 1)}
    edge_weights = {}
    for u, v, w in edges:
        adj[u].append(v)
        edge_weights[(u, v)] = w

    # Build transpose graph for SCC detection
    rev_adj = {i: [] for i in range(1, n + 1)}
    for u, v in edge_weights:
        rev_adj[v].append(u)

    # Condensation graph construction
    id_stack = list(edge_weights.keys())  # Start DFS from all nodes
    postorder = []
    visited = set()

    def dfs_rev(u):
        visited.add(u)
        for v in rev_adj[u]:
            if v not in visited:
                dfs_rev(v)
        postorder.append(u)

    for u in range(1, n + 1):
        if u not in visited:
            dfs_rev(u)

    # Assign component IDs in reverse postorder
    component = {u: -1 for u in range(1, n + 1)}
    current_comp = 0
    curr_graph = {c: set() for c in range(n + 1)}

    for u in reversed(postorder):
        comp = component[u]
        if comp == -1:
            comp = current_comp
            current_comp += 1
        for v in edge_weights:
            if v[0] == u and v[1] != u:  # Self-loops ignored in condensation usually, but let's be safe
                pass
            # Check if there is an edge from any node in comp U to any node in comp V
            # But simpler: just add outgoing edges from u to others
            for v in edge_weights:
                if v[0] == u:
                    if component[v[1]] != comp:
                        curr_graph[comp].add(component[v[1]])
        component[u] = comp

    # Check if all nodes are in the same component (SCC)
    if len(component) != 1:
        # Wait, this logic is flawed. Let's redo SCC simply.
        pass

    # Proper SCC using Tarjan's or Kosaraju's is better. Let's use Kosaraju's.
    visited2 = [False] * (n + 1)
    order = []

    def dfs1(u):
        visited2[u] = True
        for v in adj[u]:
            if not visited2[v]:
                dfs1(v)
        order.append(u)

    for i in range(1, n + 1):
        if not visited2[i]:
            dfs1(i)

    # Clear visited and use transposed graph
    visited2 = [False] * (n + 1)
    scc_ids = [-1] * (n + 1)
    scc_count = 0

    def dfs2(u, comp_id):
        visited2[u] = True
        scc_ids[u] = comp_id
        for v in rev_adj[u]:
            if not visited2[v] and scc_ids[v] == -1:
                dfs2(v, comp_id)

    for i in reversed(order):
        if not visited2[i] and scc_ids[i] == -1:
            dfs2(i, scc_count)
            scc_count += 1

    # Check if all vertices have the same SCC ID
    scc_0 = scc_ids[1]
    for i in range(2, n + 1):
        if scc_ids[i] != scc_0:
            return None

    # Now we know all nodes are in one SCC. Min weight walk visiting all.
    # This is effectively finding a minimum weight closed walk covering all nodes.
    # Since n is small (<=20), we can use DP with bitmask.
    # State: dp[mask][last] = min cost to visit set 'mask' ending at 'last'
    # Initialize: dp[1<<i][i] = 0 for all i in 1..n (0-indexed adjustment later)
    INF = float('inf')
    limit = 1 << n
    dp = [[INF] * n for _ in range(limit)]

    for start in range(n):
        dp[1 << start][start] = 0

    # Process masks by size to ensure correct order
    for mask_size in range(1, n):
        for mask in range(limit):
            if bin(mask).count('1') != mask_size:
                continue
            for last in range(n):
                if not (mask & (1 << last)):
                    continue
                if dp[mask][last] == INF:
                    continue
                u = last + 1  # 1-based
                for v, w in edge_weights.items():
                    if v == u:
                        continue
                    v_idx = v - 1
                    if not (mask & (1 << v_idx)):
                        new_mask = mask | (1 << v_idx)
                        new_cost = dp[mask][last] + w
                        if new_cost < dp[new_mask][v_idx]:
                            dp[new_mask][v_idx] = new_cost
                        elif new_cost > dp[new_mask][v_idx]:
                            # Avoid infinite loop if we are adding same node multiple times in one step
                            # But we only add if not in mask, so this is fine.
                            pass

    # The answer is the minimum over all ending nodes for the full mask
    # But wait, the walk might not return to start. It just needs to cover all.
    # So min over dp[(1<<n)-1][any] is correct.
    full_mask = limit - 1
    ans = INF
    for last in range(n):
        if dp[full_mask][last] < ans:
            ans = dp[full_mask][last]

    if ans == INF:
        return None

    return int(ans)

from typing import List

def findProductQueries(queries: List[List[int]]) -> List[int]:
    # 0-th bit
    def q_n(n: int) -> int:
        if n == 0:
            return 0
        M = n >> 1
        if M == 0:
            return 1
        r = n & 1 - (1 << (n.bit_length() - 1))
        if M == n:
            return (1 << n.bit_length()) + 2 * q_n(M + (r ^ n))
        return (1 << n.bit_length()) + q_n(M + (r ^ n)) + q_n(M - (r ^ M))

    def q(n: int) -> int:
        if n == 0:
            return 0
        M = n >> 1
        if M == 0:
            return 1
        return q_n(n) - q(M - (n.bit_length() - 1) + (n & 1))

    def S(n: int) -> int:
        if n <= 0:
            return 0
        bit = (n.bit_length() - 1)
        count = (1 << (bit + 1)) * bit
        r = n
        while r > 0:
            bit = (r.bit_length() - 1)
            count += (1 << bit)
            r -= (1 << bit)
        return count

    def find_number(idx: int) -> int:
        lo, hi = 0, 2000000000000000
        while lo < hi:
            mid = (lo + hi) // 2
            if S(mid) <= idx:
                lo = mid + 1
            else:
                hi = mid
        return lo

    results = []
    for from_i, to_i, mod_i in queries:
        start_num = find_number(from_i)
        end_num = find_number(to_i)

        total_exponent = 0

        if start_num == end_num:
            total_exponent = q(to_i + 1) - q(from_i + 1)
        else:
            total_exponent += q(to_i + 1) - q(S(start_num) + 1) + q(S(end_num)) - q(S(start_num))
            total_exponent += S(end_num) - S(start_num)

        if mod_i == 1:
            results.append(0)
        else:
            res = pow(2, total_exponent, mod_i) if total_exponent > 0 else 1
            results.append(res)

    return results

def count_good_strings(n: int, k: int, s: str) -> int:
    MOD = 998244353

    if k == 1:
        return 0
    if k > n:
        return pow(2, s.count('?'), MOD)

    # Represent 'A' as 0 and 'B' as 1
    def get_val(c):
        if c == 'A': return 0
        if c == 'B': return 1
        return -1

    # Initial state: before any char, the window of size k-1 is all empty/padding (-1)
    # We store a tuple of length k-1
    initial_mask = tuple([-1] * (k - 1))
    dp = {initial_mask: 1}

    for i in range(n):
        new_dp = {}
        c = s[i]
        if c == '?':
            vals = [0, 1]
        else:
            vals = [get_val(c)]

        for prev_mask, count in dp.items():
            for val in vals:
                # Construct full window of length k ending at i
                # The previous mask holds the k-1 chars before this position
                window = list(prev_mask)
                window.append(val)
                # window is now 0..k-1 where window[0] corresponds to index i-k+1
                # window[k-1] corresponds to index i

                is_palindrome = True
                for j in range(k // 2):
                    if window[j] != window[k - 1 - j]:
                        is_palindrome = False
                        break

                if is_palindrome:
                    continue

                # New state is the last k-1 characters: s[i-k+2 : i+1]
                # Which is prev_mask[1:] plus the new val
                next_mask = tuple(prev_mask[1:]) + (val,)

                # Update count
                if next_mask in new_dp:
                    new_dp[next_mask] = (new_dp[next_mask] + count) % MOD
                else:
                    new_dp[next_mask] = count

        dp = new_dp
        if not dp:
            break

    return sum(dp.values()) % MOD

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    memo = {}  # (r, c, K, path_length, frozenset of visited) -> count would be too complex, stick to simple recursion

    # Parse grid to find blocked cells
    blocked = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#':
                blocked.add((r, c))

    count = 0

    # Recursive DFS helper
    def dfs(r: int, c: int, steps_left: int, visited: frozenset):
        nonlocal count

        # Base case: if we have made K moves (K+1 cells total), count this path
        if steps_left == 0:
            count += 1
            return

        # Explore neighbors
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check bounds
            if 0 <= nr < H and 0 <= nc < W:
                # Check not blocked and not visited
                if (nr, nc) not in blocked and (nr, nc) not in visited:
                    new_visited = visited | {(nr, nc)}
                    dfs(nr, nc, steps_left - 1, new_visited)

    # Start DFS from every cell that is the starting point
    # Since 'starting from any empty cell' implies the path of length K+1 includes the start cell
    for r in range(H):
        for c in range(W):
            if (r, c) not in blocked:
                dfs(r, c, K, frozenset([(r, c)]))

    return count

