def max_eleven_twentytwo_subsequence(s: str, l: int, r: int) -> int:
    substring = s[l-1:r]
    n = len(substring)
    if n == 0:
        return 0

    slash_idx = -1
    for i in range(n):
        if substring[i] == '/':
            slash_idx = i
            break

    if slash_idx == -1:
        return 0

    cnt1 = sum(1 for i in range(slash_idx) if substring[i] == '1')
    cnt2 = sum(1 for i in range(slash_idx + 1, n) if substring[i] == '2')

    if cnt2 < 1:
        return 0

    k = min(cnt1, cnt2 - 1)
    return 2 * k + 1

