        adj[u].append(v)

    n_row = range(N + 1)

    def mat_mul(A, B):
        res = [[0] * (N + 1) for _ in range(N + 1)]
        for i in n_row:
            for k in n_row:
                if A[i][k] == 0:
                    continue
                for j in n_row:
                    res[i][j] = (res[i][j] + A[i][k] * B[k][j]) % MOD
        return res

    def mat_pow(A, p):
        result = [[0] * (N + 1) for _ in range(N + 1)]
        for i in n_row:
            result[i][i] = 1
        base = [row[:] for row in A]
        while p > 0:
            if p % 2 == 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            p //= 2
        return result

    # Use 0-indexing for matrix: row i, col j represents edge i+1 -> j+1
    # We need to track count at vertex 1 (index 0) after K steps.
    # Vectors are row vectors v * M. v_0 = [1, 0, ...]. v_K = v_0 * M^K.
    # Answer is v_K[0] = (M^K)[0][0].

    matrix = [[0] * N for _ in range(N)]
    for u in range(1, N + 1):
        for v in adj[u]:
            matrix[u-1][v-1] = 1

    MK = mat_pow(matrix, K)
