    MOD = 10**9 + 7
    if n == 1:
        if k == 0:
            return m % MOD
        else:
            return 0

    # dp[j] stores the number of arrays of current length with exactly j equal pairs
    dp = [0] * (k + 1)
    dp[0] = m  # Base case: length 1, 0 pairs, m choices

    for i in range(2, n + 1):
        new_dp = [0] * (k + 1)
        # If previous had j-1 pairs, adding same value -> j pairs (m choices)
        for j in range(1, k + 1):
            new_dp[j] = (new_dp[j] + dp[j - 1] * m) % MOD
        # If previous had j pairs, adding different value -> j pairs (m-1 choices)
        for j in range(k + 1):
            if j < len(dp):
                new_dp[j] = (new_dp[j] + dp[j] * (m - 1)) % MOD
        dp = new_dp

    return dp[k]

