        if n <= 0 or n == 1:
            return False
        temp = n
        factors = {}
        d = 2
        while d * d <= temp:
            while temp % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1

        if len(factors) != 2:
            return False

        for exp in factors.values():
            if exp % 2 != 0:
                return False

        return True

    if a < 2:
        return 0

    n = a
    while True:
        if is_400_number(n):
            return n
        n -= 1

    return -1

