def digit_sum_dp(n: int, target_min: int, target_max: int) -> int:
    s = str(n)
    L = len(s)

    # State: (index, current_sum, tight, leading_zeros)
    @lru_cache(maxsize=None)
    def dp(idx, cur_sum, tight, leading_zeros):
        if idx == L:
            if cur_sum >= target_min and cur_sum <= target_max:
                return 1
            return 0

        limit = int(s[idx]) if tight else 9
        res = 0

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)
            new_zeros = leading_zeros and (digit == 0)
            new_sum = cur_sum + digit if not new_zeros else cur_sum

            res = (res + dp(idx + 1, new_sum, new_tight, new_zeros)) % MOD

        return res

    return dp(0, 0, True, True)

