def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)
    INF = float('inf')

    # Precompute min cost for each substring s[i:j+1] (inclusive indices i to j)
    # cost[i][j] stores the minimum changes needed for substring s[i..j]
    cost = [[INF] * n for _ in range(n)]

    for i in range(n):
        for j in range(i, n):
            L = j - i + 1
            if L < 2:
                continue

            best_cost = INF
            # Check all d such that 1 <= d < L and L % d == 0
            for d in range(1, L):
                if L % d != 0:
                    continue

                current_cost = 0
                valid_d = True

                # For each residue r modulo d, check if positions in substring form a palindrome
                # Positions in substring are i, i+1, ..., j
                # Local index p in 0..L-1. We group by p % d.
                for r in range(d):
                    seq = []
                    p = r
                    while p < L:
                        seq.append(s[i + p])
                        p += d

                    # Check if seq is a palindrome
                    m = len(seq)
                    is_pal = True
                    for x in range(m // 2):
                        if seq[x] != seq[m - 1 - x]:
                            is_pal = False
                            break

                    if not is_pal:
                        # We need to change characters to make this sequence a palindrome
                        # Cost is number of mismatches in the middle
                        mismatches = 0
                        for x in range(m // 2):
                            if seq[x] != seq[m - 1 - x]:
                                mismatches += 1
                        current_cost += mismatches
                    else:
                        # No cost to make it a palindrome (it already is)
                        current_cost += 0

                if current_cost < best_cost:
                    best_cost = current_cost

            cost[i][j] = best_cost

    # DP: dp[i][m] = min changes to partition first i chars into m semi-palindromes
    # i ranges from 0 to n (number of chars processed)
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for m in range(1, k + 1):
            # Try all possible split points j for the last substring s[j:i]
            for j in range(m - 1, i):
                # Last substring is s[j:i] (exclusive of i, inclusive of j)
                # Length is i - j
                sub_len = i - j
                if sub_len < 2:
                    continue

                c_sub = cost[j][i-1]
                if c_sub != INF:
                    if dp[j][m-1] != INF:
                        if dp[j][m-1] + c_sub < dp[i][m]:
                            dp[i][m] = dp[j][m-1] + c_sub

    return int(dp[n][k])

