def power(base: int, exp: int, mod: int) -> int:
    result = 1
    base %= mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp //= 2
    return result

def sum_of_subarray_powers(n: int, k: int, a: List[int]) -> int:
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = (prefix[i] + a[i]) % MOD

    total = 0
    for l in range(n):
        for r in range(l, n):
            sub_sum = (prefix[r+1] - prefix[l] + MOD) % MOD
            term = power(sub_sum, k, MOD)
            total = (total + term) % MOD

    return total

