def solve(input):
    nums = input['nums']
    k = input['k']
    n = len(nums)

    # dp[i][j] = maximum length of a good subsequence ending at index i with exactly j mismatches between neighbors in the subsequence.
    # A subsequence s[0]...s[m-1] has j mismatches if there are j indices p in {0, ..., m-2} such that s[p] != s[p+1].
    # We need to find max(dp[i][j]) for all i, all j <= k.

    dp = [[0] * (k + 1) for _ in range(n)]

    # Initialize
    for i in range(n):
        for j in range(k + 1):
            dp[i][j] = 1  # A single element has 0 mismatches

    # Fill DP
    for i in range(1, n):
        for j in range(k + 1):
            # Option 1: The last element of the subsequence is nums[i].
            # It could be appended to a subsequence ending at prev_i.
            # If nums[prev_i] == nums[i], the number of mismatches doesn't increase.
            # If nums[prev_i] != nums[i], the number of mismatches increases by 1.

            if j == 0:
                # Must have nums[prev_i] == nums[i]
                best_len = 1  # At least the element itself
                for prev_i in range(i):
                    if nums[prev_i] == nums[i]:
                        best_len = max(best_len, dp[prev_i][0] + 1)
                dp[i][0] = best_len
            else:
                # For j > 0, we can come from:
                # 1. prev with same value -> transition from dp[prev][j]
                # 2. prev with different value -> transition from dp[prev][j-1]
                max_len = 1
                # Case 1: Same value, same mismatch count
                for prev_i in range(i):
                    if nums[prev_i] == nums[i]:
                        if dp[prev_i][j] != 0:
                            max_len = max(max_len, dp[prev_i][j] + 1)

                # Case 2: Different value, mismatch count decreases by 1
                for prev_i in range(i):
                    if nums[prev_i] != nums[i]:
                        if dp[prev_i][j-1] != 0:
                            max_len = max(max_len, dp[prev_i][j-1] + 1)
                dp[i][j] = max_len

    # The answer is the maximum length found in any dp[i][j] where j <= k.
    ans = 0
    for j in range(k + 1):
        for i in range(n):
            ans = max(ans, dp[i][j])
    return ans

