def solve(stream, registers):
    # Read 8 bits from stream
    bits = []
    for _ in range(8):
        b = stream.next_bit()
        if b is not None:
            bits.append(b)

    if len(bits) < 8:
        # Fallback if stream ends early (should not happen per spec)
        return 0

    # Convert bits to n, t using the mapping: v = binary(bits), n = v % 4 + 1, t = v // 4
    v = 0
    for bit in bits:
        v = v * 2 + bit
    n = v % 4 + 1
    t = v // 4

    # Initialize pyramid grid. Row i has i+1 glasses.
    glass_amount = [[0.0] * (i + 1) for i in range(n)]
    glass_amount[0][0] = float(t)

    # Simulate flow from row i to row i+1
    for i in range(n - 1):
        for j in range(len(glass_amount[i])):
            if glass_amount[i][j] > 1.0:
                overflow = glass_amount[i][j] - 1.0
                glass_amount[i][j] = 1.0  # Full
                # Distribute overflow equally to the two glasses below
                glass_amount[i + 1][j] += overflow / 2.0
                if j + 1 < len(glass_amount[i + 1]):
                    glass_amount[i + 1][j + 1] += overflow / 2.0

    # Count fully filled glasses (>= 1.0)
    ans = 0
    for i in range(n):
        for j in range(len(glass_amount[i])):
            if glass_amount[i][j] >= 1.0:
                ans += 1

    return ans

